 d['durable_files']={str(p.relative_to(root)).replace('\\','/'):{'sha256':sha(p),'size':p.stat().st_size if p.is_file() else None} for p in [root/'config/bridge.toml',root/'data/bridge.db',root/'data/manual_consumption.json',root/'uninstall.ps1']}
 db=root/'data/bridge.db';conn=sqlite3.connect(db.as_uri()+'?mode=ro',uri=True,timeout=5);conn.execute('PRAGMA query_only=ON');d['sqlite_quick_check']=conn.execute('PRAGMA quick_check').fetchall();d['database_identity']={'device':db.stat().st_dev,'inode':db.stat().st_ino};d['dispatch_identities']=[{'dispatch_id':row[0],'state':row[1],'payload_hash':row[2]} for row in conn.execute('SELECT dispatch_id,state,payload_hash FROM dispatches ORDER BY dispatch_id')];d['database_tables']={};
 for (table,) in conn.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"):
  assert re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',table);rows=conn.execute('SELECT * FROM '+table).fetchall();normalized=sorted(json.dumps(row,sort_keys=True,default=lambda x: {'bytes_sha256':hashlib.sha256(x).hexdigest()}) for row in rows);d['database_tables'][table]={'rows':len(rows),'logical_sha256':hashlib.sha256(json.dumps(normalized).encode()).hexdigest()}
